column3:
%p = { lang:"t" lowering:"typescript" indent:{unit:" " width:2} ident:{case:{record:"pascal" field:"camel" alias:"pascal" enum:"pascal" member:"pascal"}} types:{prim:{string:"string" int:"number"} union:{prec:1 childPrec:2}} }
%g = { lang:"g" lowering:"go" indent:{unit:"\t" width:1} ident:{case:{alias:"pascal"}} types:{prim:{string:"string"}} }
t: lowerdecls([{k:"alias" name:"user_id" type:{k:"prim" prim:"string"}}], %p)
g: lowerdecls([{k:"alias" name:"user_id" type:{k:"prim" prim:"string"}}], %g)

%p = { lang:"t" lowering:"typescript" indent:{unit:" " width:2} ident:{case:{record:"pascal" field:"camel" alias:"pascal" enum:"pascal" member:"pascal"}} types:{prim:{string:"string" int:"number"} union:{prec:1 childPrec:2}} }
records: { user: { name:"user" fields:[{name:"id" t:"string"}] } }
x: emit($.records, {
  match: name: string
  body: [ file(.name + ".ts", lowerdecls([{
    k: "record" name: .name
    fields: emit(.fields, { match: name: string
      body: [{ name: .name type: { k:"prim" prim: match(.t, "string", "string") } }] })
